def parse_data():
    """把 DATA 字符串拆成 100 题的 list of dict"""
    qs = []
    for line in DATA.strip().split('\n'):
        parts = line.split('|')
        if len(parts) != 12:
            print(f'BAD LINE ({len(parts)} parts): {line[:80]}')
            continue
        qid, qtype, chap, stem, oA, oB, oC, oD, oE, ans, expl, kp = parts
        opts = {}
        for k, v in [('A',oA),('B',oB),('C',oC),('D',oD),('E',oE)]:
            if v:
                opts[k] = v
        qs.append({
            'id': qid, 'type': qtype, 'chapter': chap, 'stem': stem,
            'options': opts, 'answer': ans, 'explain': expl, 'kp': kp,
        })
    return qs

if __name__ == '__main__':
    qs = parse_data()
    from collections import Counter
    print('total:', len(qs))
    print('by type:', Counter(q['type'] for q in qs))
    print('by chapter:', Counter(q['chapter'] for q in qs))
